const raw = $input.first().json;
const b = raw.body ?? raw;
const errors = [];
const isStr = (v) => typeof v === 'string' && v.trim() !== '';
const isNum = (v) => typeof v === 'number' && Number.isFinite(v);
const isRate = (v) => isNum(v) && v >= 0 && v <= 1;

if (!b || typeof b !== 'object') {
  errors.push('corps JSON absent ou invalide');
} else {
  const f = b.facture, p = b.prediction, s = b.explicabilite_shap, a = b.liens_action;
  if (b.event !== 'FRAUD_ALERT') errors.push("event doit valoir 'FRAUD_ALERT'");
  if (!f || typeof f !== 'object') {
    errors.push('facture manquante');
  } else {
    if (!isStr(f.facture_id)) errors.push('facture.facture_id manquant');
    if (!isStr(f.prestataire_id)) errors.push('facture.prestataire_id manquant');
    if (!isStr(f.assure_id)) errors.push('facture.assure_id manquant');
    if (!isNum(f.montant_total)) errors.push('facture.montant_total doit etre numerique');
    if (!isNum(f.montant_demande)) errors.push('facture.montant_demande doit etre numerique');
  }
  if (!p || typeof p !== 'object') {
    errors.push('prediction manquante');
  } else {
    if (!isRate(p.score_fraude)) errors.push('prediction.score_fraude doit etre un nombre entre 0 et 1');
    if (!isRate(p.seuil_applique)) errors.push('prediction.seuil_applique doit etre un nombre entre 0 et 1');
    if (!isStr(p.version_modele)) errors.push('prediction.version_modele manquant');
  }
  if (!s || typeof s !== 'object' || !isStr(s.facteur_principal)) {
    errors.push('explicabilite_shap.facteur_principal manquant');
  }
  if (!a || typeof a !== 'object' || !isStr(a.dashboard_url) || !/^https?:\/\//.test(a.dashboard_url)) {
    errors.push('liens_action.dashboard_url manquant ou invalide');
  }
}

return [{ json: { ...(b && typeof b === 'object' ? b : {}), valid: errors.length === 0, errors } }];

const item = $input.first().json;
const f = item.facture;
const p = item.prediction;
const s = item.explicabilite_shap;
const a = item.liens_action;

const html = (v) => String(v ?? 'N/A')
  .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
const slk = (v) => String(v ?? 'N/A')
  .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const ar = (n) => String(Math.round(n)).replace(/\B(?=(\d{3})+(?!\d))/g, ' ') + ' Ar';
const score = p.score_fraude.toFixed(2);
const seuil = p.seuil_applique.toFixed(2);
const second = s.facteur_secondaire || null;
const reco = s.recommandation || null;

let slack_text =
  ':rotating_light: *ALERTE FRAUDE - PrediCare TPA*\n' +
  `- *Facture* : \`${slk(f.facture_id)}\`` + (f.numero_facture ? ` (N° ${slk(f.numero_facture)})` : '') + '\n' +
  `- *Prestataire* : \`${slk(f.prestataire_id)}\` | *Assuré* : \`${slk(f.assure_id)}\`\n` +
  `- *Montant total* : ${ar(f.montant_total)} (demandé : ${ar(f.montant_demande)})\n` +
  `- *Score de risque* : *${score}* (seuil : ${seuil}) | modèle \`${slk(p.version_modele)}\`\n` +
  `- *Facteur principal* : ${slk(s.facteur_principal)}\n` +
  (second ? `- *Facteur secondaire* : ${slk(second)}\n` : '') +
  (reco ? `- *Recommandation* : ${slk(reco)}\n` : '') +
  `<${a.dashboard_url}|Ouvrir le dossier dans le tableau de bord>`;

const email_subject = `[ALERTE FRAUDE] Facture ${f.facture_id} - score ${score}`;

const email_html =
  '<h2>Alerte détection de fraude - PrediCare TPA</h2>' +
  '<p>Le score de risque d\'une facture dépasse le seuil configuré. Un contrôle est requis.</p>' +
  '<ul>' +
  `<li><b>Facture :</b> ${html(f.facture_id)}` + (f.numero_facture ? ` (N° ${html(f.numero_facture)})` : '') + '</li>' +
  `<li><b>Prestataire :</b> ${html(f.prestataire_id)}</li>` +
  `<li><b>Assuré :</b> ${html(f.assure_id)}</li>` +
  `<li><b>Montant total :</b> ${ar(f.montant_total)} (demandé : ${ar(f.montant_demande)})</li>` +
  `<li><b>Score de risque :</b> <b style="color:#c00000;">${score}</b> (seuil : ${seuil})</li>` +
  `<li><b>Version du modèle :</b> ${html(p.version_modele)}</li>` +
  '</ul>' +
  '<h3>Rapport d\'explicabilité</h3>' +
  '<ul>' +
  `<li><b>Facteur principal :</b> ${html(s.facteur_principal)}</li>` +
  (second ? `<li><b>Facteur secondaire :</b> ${html(second)}</li>` : '') +
  (reco ? `<li><b>Recommandation :</b> ${html(reco)}</li>` : '') +
  '</ul>' +
  `<p><a href="${html(a.dashboard_url)}" style="background:#0055ff;color:#ffffff;padding:10px 16px;text-decoration:none;border-radius:4px;">Consulter le dossier</a></p>`;

return [{ json: { ...item, slack_text, email_subject, email_html } }];
